blocks.code:
.box-visible {
  overflow: visible; /* по умолчанию: контент вылезает */
}

.box-hidden {
  overflow: hidden;  /* обрезается */
}

.box-auto {
  overflow: auto;    /* прокрутка при необходимости */
}

.box-scroll {
  overflow: scroll;  /* прокрутка всегда */
}

.box {
  overflow-x: hidden;  /* горизонтальная прокрутка запрещена */
  overflow-y: auto;    /* вертикальная прокрутка при необходимости */
}

.no-wrap {
  white-space: nowrap;  /* текст не переносится */
  overflow: hidden;     /* обрезается если не влезает */
  text-overflow: ellipsis; /* показывает «...» если обрезан */
}

/* Элемент исчезает, место освобождается */
.none { display: none; }

/* Элемент скрыт, но место сохраняется */
.hidden { visibility: hidden; }

/* Элемент прозрачный, но на месте и кликается */
.transparent { opacity: 0; }

.title {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 200px;
}

.code-block {
  max-height: 200px;
  overflow-y: auto;
  background: #f5f5f5;
  padding: 16px;
  font-family: monospace;
}

.menu {
  visibility: hidden;
  opacity: 0;
  transition: opacity 0.3s, visibility 0.3s;
}

.menu.open {
  visibility: visible;
  opacity: 1;
}
